using System.Threading.Tasks;
using Garnet.cluster;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Garnet.Tests.cluster
{
    public class ReplicaSyncSessionTests
    {
        [Fact]
        public async Task SendCheckpointAsync_LogsErrorWhenAddressIsNull()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();
            var mockClusterProvider = new Mock<ClusterProvider>();
            var mockClusterManager = new Mock<ClusterManager>();
            var mockCurrentConfig = new Mock<CurrentConfig>();

            string replicaNodeId = "replica1";

            // Setup CurrentConfig.GetWorkerAddressFromNodeId to return null address and -1 port
            mockCurrentConfig.Setup(c => c.GetWorkerAddressFromNodeId(replicaNodeId))
                .Returns((null, -1));

            mockClusterManager.SetupGet(c => c.CurrentConfig).Returns(mockCurrentConfig.Object);
            mockClusterProvider.SetupGet(p => p.clusterManager).Returns(mockClusterManager.Object);

            var session = new ReplicaSyncSession(
                null,
                mockClusterProvider.Object,
                replicaNodeId: replicaNodeId,
                logger: mockLogger.Object);

            // Act
            var result = await session.SendCheckpointAsync();

            // Assert
            Assert.False(result);
            mockLogger.Verify(l => l.Log(
                LogLevel.Error,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("don't know about replicaId")),
                null,
                It.IsAny<Func<It.IsAnyType, System.Exception, string>>()),
                Times.Once);
        }
    }
}
